select * from (values
('¿Cómo reservo?','How do I book?','Elige tu alojamiento y tus fechas y pulsa «Consultar por WhatsApp». Te confirmamos la disponibilidad y el precio directamente, sin intermediarios.','Choose your stay and dates and tap “Enquire on WhatsApp”. We confirm availability and price directly, with no middlemen.',false,0),
('¿El precio que veo es definitivo?','Is the price I see final?','El precio «desde» es orientativo: el importe final depende de las fechas, la temporada y el número de personas. Te lo confirmamos por WhatsApp antes de reservar.','The “from” price is indicative: the final amount depends on dates, season and number of guests. We confirm it on WhatsApp before you book.',false,1),
('¿El calendario está actualizado en tiempo real?','Is the calendar updated in real time?','Se actualiza periódicamente a partir de los calendarios de nuestras plataformas, por lo que puede haber un pequeño retraso. Siempre confirmamos la disponibilidad contigo antes de cerrar la reserva.','It refreshes periodically from our platforms'' calendars, so there can be a short delay. We always confirm availability with you before finalising a booking.',false,2),
('¿Cómo se paga la reserva?','How is the booking paid?','Se abona el 50 % del importe total al reservar y el resto 7 días antes de la llegada. No se requiere fianza.','50% of the total is paid when booking and the remainder 7 days before arrival. No security deposit is required.',true,3),
('¿Se puede cancelar la reserva?','Can I cancel my booking?','Los pagos realizados son no reembolsables. Si tienes dudas sobre tus fechas, consúltanos antes de reservar.','Payments made are non-refundable. If you are unsure about your dates, ask us before booking.',true,4),
('¿A qué hora es la llegada y la salida?','What are the check-in and check-out times?','Con carácter general, la llegada es a partir de las 16:00 y la salida hasta las 11:00. Algunos alojamientos pueden variar; te lo confirmamos al reservar.','In general, check-in is from 16:00 and check-out until 11:00. Some stays may differ; we confirm it when you book.',true,5),
('¿Dónde están los alojamientos?','Where are the stays?','En Málaga, Torremolinos, Benalmádena y Fuengirola, en la Costa del Sol. Te facilitamos la dirección exacta una vez confirmada la reserva.','In Málaga, Torremolinos, Benalmádena and Fuengirola on the Costa del Sol. We share the exact address once your booking is confirmed.',false,6),
('¿Cómo es la llegada?','What is arrival like?','Algunos alojamientos, como Loft Ipanema, tienen llegada autónoma. Para el resto te explicamos todo el proceso al confirmar la reserva.','Some stays, such as Loft Ipanema, offer self check-in. For the rest we explain the whole process when you confirm your booking.',false,7),
('¿Se admiten mascotas?','Are pets allowed?','Jardín del Mediterráneo admite mascotas. En el resto de alojamientos, consúltanos por WhatsApp y te lo confirmamos.','Mediterranean Garden House allows pets. For the other stays, ask us on WhatsApp and we''ll confirm.',true,8),
('¿Se pueden organizar fiestas?','Are parties allowed?','No. Nuestros alojamientos están en edificios o zonas residenciales y pedimos respetar el descanso de los vecinos.','No. Our stays are in residential buildings or areas and we ask guests to respect the neighbours'' rest.',true,9),
('¿Qué atención recibo durante la estancia?','What support do I get during my stay?','Atención personalizada durante toda tu estancia: cualquier duda o incidencia, escríbenos por WhatsApp.','Personal attention throughout your stay: for any question or issue, message us on WhatsApp.',false,10)
) as v(q_es,q_en,a_es,a_en,needs_review,sort)
where not exists (select 1 from public.faq);

select * from (values
('Una estancia increíble con vistas espectaculares al mar y una ubicación perfecta cerca de todo. El alojamiento cumplió totalmente las expectativas y la atención de Virginia fue excepcional. Sin duda, una experiencia muy recomendable y para repetir.','An incredible stay with spectacular sea views and a perfect location close to everything. The accommodation fully met our expectations and Virginia''s attention was exceptional. Highly recommended, and we''d happily come back.','Huésped de VirAnd','VirAnd guest',5,0),
('Disfrutamos muchísimo de nuestra estancia. La atención de Virginia fue excelente y el apartamento contaba con todo lo necesario para una experiencia cómoda y relajante. La ubicación, junto a la playa y restaurantes, hizo que todo fuera aún más perfecto.','We really enjoyed our stay. Virginia''s attention was excellent and the apartment had everything needed for a comfortable, relaxing experience. The location, next to the beach and restaurants, made everything even better.','Huésped de VirAnd','VirAnd guest',5,1),
('Una experiencia impecable, en una ubicación perfecta y con una atención excepcional por parte de Virginia.','A flawless experience, in a perfect location with exceptional attention from Virginia.','Huésped de VirAnd','VirAnd guest',5,2)
) as v(text_es,text_en,author_es,author_en,rating,sort)
where not exists (select 1 from public.reviews);

on conflict (key,lang) do nothing;
