insert into public.flats (slug,active,name_es,name_en,zona,barrio,lat,lng,viajeros,dormitorios,camas,banos,servicios,desc_es,desc_en,nota,base_price,sort) values
('atico-benalmadena',true,'Ático frente a la playa con jacuzzi climatizado','Beachfront penthouse with heated jacuzzi','Benalmádena','Playa',36.5955,-4.5695,4,2,2,1,array['playa','jacuzzi','barbacoa']::text[],'Apartamento entero en Benalmádena, frente a la playa, con jacuzzi climatizado y barbacoa en su terraza. Alojamiento para 4 viajeros con 2 dormitorios.','Entire apartment in Benalmádena, right on the beach, with a heated jacuzzi and barbecue on the terrace. Sleeps 4 guests in 2 bedrooms.',null,null,0),
('cosy-flat-malaga',true,'Cosy Flat en el corazón de Málaga','Cosy Flat in the heart of Málaga','Málaga','Centro',36.7213,-4.4214,4,2,2,2,array['centro','parking','acogedor']::text[],'Apartamento entero acogedor en el centro de Málaga, con parking. Alojamiento para 4 viajeros con 2 dormitorios y 2 baños.','Cosy entire apartment in central Málaga, with parking. Sleeps 4 guests in 2 bedrooms with 2 bathrooms.',null,null,1),
('apartamento-playa-malaga',true,'Encantador apartamento en la playa','Charming beach apartment','Málaga','Playa',36.719,-4.386,6,3,5,2,array['playa','piscina','parking']::text[],'Apartamento entero en Málaga junto a la playa, con piscina y parking. Alojamiento para 6 viajeros con 3 dormitorios y 2 baños.','Entire apartment in Málaga by the beach, with a pool and parking. Sleeps 6 guests in 3 bedrooms with 2 bathrooms.',null,null,2),
('boho-chic-torremolinos',true,'Boho Chic frente a la playa','Boho Chic on the beachfront','Torremolinos','Playa',36.62,-4.499,7,2,5,1,array['playa','piscina','bicicletas']::text[],'Apartamento entero en Torremolinos frente a la playa, con piscina y bicicletas. Alojamiento para 7 viajeros con 2 dormitorios.','Entire apartment in Torremolinos on the beachfront, with a pool and bicycles. Sleeps 7 guests in 2 bedrooms.',null,null,3),
('loft-ipanema-malaga',true,'Loft Ipanema, Málaga Centro','Loft Ipanema, Málaga Centre','Málaga','Centro',36.7255,-4.434,2,1,1,1,array['llegada-autonoma','wifi']::text[],'Acogedor loft completamente reformado situado en una de las zonas más auténticas de Málaga. A tan solo 15 minutos caminando del centro histórico y rodeado de supermercados, restaurantes, farmacia y todos los servicios necesarios para una estancia cómoda.','Cosy, fully renovated loft in one of Málaga''s most authentic neighbourhoods. Just a 15-minute walk from the historic centre, surrounded by supermarkets, restaurants, a pharmacy and everything you need for a comfortable stay.',4.9,null,4),
('benalmarina-apartment',true,'Benalmarina Apartment','Benalmarina Apartment','Benalmádena','Benalmarina',36.5871,-4.5368,4,2,null,1,array['piscina','parking','aire','wifi']::text[],'Apartamento en una zona tranquila de Benalmádena, a solo 5 minutos a pie de la playa. Dispone de dos amplios dormitorios, terraza para disfrutar de las noches de verano, plaza de parking y acceso a dos piscinas.','Apartment in a quiet area of Benalmádena, just a 5-minute walk from the beach. It has two spacious bedrooms, a terrace for summer evenings, a parking space and access to two swimming pools.',null,109,5),
('carvajal-beach-apartment',true,'Carvajal Beach apartment','Carvajal Beach apartment','Fuengirola','Carvajal',36.5713,-4.5889,3,1,null,1,array['vistas-mar','parking','aire','wifi']::text[],'Acogedor apartamento con amplia terraza y vistas espectaculares al mar, ideal para disfrutar del sol de la Costa del Sol en invierno. Dormitorio con cama de 1,50 m y vistas al mar, cama supletoria de 0,90 m para una tercera persona, salón con sofá, TV con canales internacionales y Netflix, y aparcamiento privado en el mismo edificio. Restaurantes, chiringuitos, supermercado y gasolinera en la zona.','Cosy apartment with a large terrace and spectacular sea views, ideal for enjoying the Costa del Sol sun in winter. Bedroom with a 1.5 m bed and sea views, a 0.9 m extra bed for a third guest, a living room with sofa, TV with international channels and Netflix, and private parking in the same building. Restaurants, beach bars, a supermarket and a petrol station nearby.',null,105,6),
('guadalmar-paraje-natural',true,'Guadalmar (Paraje Natural)','Guadalmar (Natural Area)','Málaga','Guadalmar',36.6643,-4.4604,3,1,null,1,array['piscina','vistas','aire','wifi']::text[],'Apartamento totalmente reformado en el paraje natural de Guadalmar, con vistas a la playa, la montaña y el campo de golf. Salón comedor con Smart TV, Netflix y wifi de alta velocidad, cocina totalmente equipada, dormitorio con amplio armario y baño completo. Rodeado de restaurantes de cocina local.','Fully renovated apartment in the Guadalmar natural area, with views of the beach, the mountains and the golf course. Living-dining room with Smart TV, Netflix and high-speed wifi, a fully equipped kitchen, a bedroom with a large wardrobe and a full bathroom. Surrounded by restaurants serving local cuisine.',null,95,7),
('jardin-del-mediterraneo',true,'Jardín del Mediterráneo','Mediterranean Garden House','Málaga',null,36.7215,-4.3062,6,3,null,4,array['piscina','jardin','parking','mascotas','barbacoa','aire']::text[],'Casa acogedora con amplio jardín, piscina privada y un sótano con mesa de billar. Cuenta con chimenea, parking privado, cocina totalmente equipada con lavadora y secadora, y dormitorios con baño en suite. Rodeada de naturaleza y silencio. Se admiten mascotas.','Welcoming house with a large garden, a private pool and a basement with a pool table. It has a fireplace, private parking, a fully equipped kitchen with washer and dryer, and bedrooms with en-suite bathrooms. Surrounded by nature and silence. Pets are welcome.',null,300,8),
('la-casita-de-la-carihuela',true,'La casita de la Carihuela','La Casita de la Carihuela','Torremolinos','La Carihuela',36.6143,-4.5045,2,1,null,1,array['vistas-mar','wifi','aire','ascensor']::text[],'Estudio frente al mar en La Carihuela, con vistas al mar, mucha luz natural y un diseño moderno y cuidado. Smart TV de gran tamaño, wifi y aire acondicionado.','Seafront studio in La Carihuela, with sea views, plenty of natural light and a modern, carefully designed interior. Large Smart TV, wifi and air conditioning.',null,65,9),
('luxy-beach-apartment',true,'Luxy Beach Apartment','Luxy Beach Apartment','Torremolinos','Bajondillo',36.6237,-4.4959,2,1,null,1,array['vistas-mar','piscina','wifi','aire','ascensor']::text[],'Apartamento luminoso con orientación sureste y vistas al mar, en la playa de Bajondillo, una de las mejores zonas de Torremolinos. Decoración ecléctica, salón con Smart TV de 65 pulgadas y wifi de 600 Mbps, ventanal abierto al mar, dormitorio con cama de 160x200 y cocina de diseño con electrodomésticos de alta gama.','Bright south-east facing apartment with sea views, on Bajondillo beach, one of the best areas of Torremolinos. Eclectic decor, a living room with a 65-inch Smart TV and 600 Mbps wifi, a large window opening onto the sea, a bedroom with a 160x200 bed and a designer kitchen with high-end appliances.',null,150,10),
('luzdesol-apartment',true,'Luz de Sol Apartment','Luz de Sol Apartment','Málaga',null,36.7134,-4.4405,6,3,null,1,array['aire','wifi','ascensor']::text[],'Apartamento familiar con tres amplios dormitorios y un baño con ducha, a 20 minutos del centro histórico de Málaga y a 13 minutos a pie de la estación de tren. Cocina con nevera y microondas, lavadora y TV con Netflix, Prime, Disney y Max. Plaza de parking gratuita a 400 metros, solo para coche de 5 plazas.','Family apartment with three spacious bedrooms and a bathroom with shower, 20 minutes from the historic centre of Málaga and a 13-minute walk from the train station. Kitchen with fridge and microwave, washing machine and a TV with Netflix, Prime, Disney and Max. Free parking space 400 metres away, for a 5-seater car only.',null,210,11),
('sol-centro-malaga',true,'Sol & Centro Málaga','Sol & Centro Málaga','Málaga','Centro',36.7248,-4.4199,2,1,null,1,array['centro','wifi','aire','ascensor']::text[],'Apartamento moderno y acogedor en pleno centro, ideal para disfrutar de la ciudad con total comodidad. Dormitorio cuidado al detalle, salón luminoso con TV, zona de comedor y cocina totalmente equipada. Perfecto para parejas o viajeros que buscan ubicación, tranquilidad y estilo en el corazón de Málaga.','Modern, cosy apartment right in the centre, ideal for enjoying the city in comfort. A carefully styled bedroom, a bright living room with TV, a dining area and a fully equipped kitchen. Perfect for couples or travellers looking for location, calm and style in the heart of Málaga.',null,70,12),
('sol-y-mar-carvajal',true,'Sol y Mar Carvajal (parking gratuito)','Sol y Mar Carvajal (free parking)','Fuengirola','Carvajal',36.5727,-4.5897,3,1,null,1,array['vistas-mar','parking','aire','wifi']::text[],'Apartamento en una ubicación privilegiada de la playa de Carvajal, con amplia terraza equipada con sombrillas y toldos y vistas impresionantes de la costa. Parking gratuito.','Apartment in a prime spot on Carvajal beach, with a large terrace equipped with parasols and awnings and impressive coastal views. Free parking.',null,165,13),
('spacious-pool-torremolinos',true,'Apartamento espacioso con piscina y parking','Spacious apartment with pool and parking','Torremolinos',null,36.6276,-4.5021,9,3,null,2,array['piscina','parking','aire','wifi']::text[],'Apartamento espacioso en una zona residencial auténtica de Torremolinos, cerca del centro y de la playa. Tres dormitorios, amplio salón comedor con Smart TV y Netflix, cocina independiente equipada, baño completo con bañera, aseo adicional, aire acondicionado, piscina y parking. Mesa de comedor para 9 personas.','Spacious apartment in an authentic residential area of Torremolinos, close to the centre and the beach. Three bedrooms, a large living-dining room with Smart TV and Netflix, a separate fully equipped kitchen, a full bathroom with bathtub, an extra toilet, air conditioning, a pool and parking. Dining table for 9.',null,319,14),
('city-apartment-carranque',true,'Amplio apartamento urbano con parking gratuito','Spacious city apartment with free parking','Málaga','Carranque',36.7235,-4.4493,8,4,null,2,array['parking','aire','wifi','ascensor']::text[],'Apartamento tranquilo, elegante y luminoso de 120 m² con cuatro amplias habitaciones y dos baños, ideal para grupos grandes y familias (máximo 8 personas). En la zona de Carranque, a 13 minutos en autobús del centro histórico, a 1 minuto de un supermercado y a 3 del Hospital Regional. Edificio de viviendas: no se permiten fiestas.','Quiet, elegant and bright 120 m² apartment with four spacious bedrooms and two bathrooms, ideal for large groups and families (maximum 8 guests). In the Carranque area, 13 minutes by bus from the historic centre, 1 minute from a supermarket and 3 from the Regional Hospital. Residential building: no parties allowed.',null,150,15)
